package no.elg.ii.feature;

import com.google.common.annotations.VisibleForTesting;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.annotation.Nonnull;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.AllArgsConstructor;
import lombok.NoArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.eventbus.EventBus;

/**
 * Keeps every feature enabled or disabled according to the config.
 * <p>
 * All methods that change feature state must be called on the client thread. Callers are
 * responsible for getting there, see {@link net.runelite.client.callback.ClientThread}.
 */
@Slf4j
@Singleton
@NoArgsConstructor
@AllArgsConstructor
public class FeatureManager {

  /**
   * The currently loaded features
   */
  @VisibleForTesting
  protected final Set<StatelessFeature> activeFeatures = ConcurrentHashMap.newKeySet();

  @Inject
  @VisibleForTesting
  protected EventBus eventBus;

  @Inject
  protected Features featureInstances;

  @Inject
  @VisibleForTesting
  protected Client client;

  /**
   * Make sure all features are in its correct state
   */
  public void updateAllFeatureStatus() {
    featureInstances.forEach(this::updateFeatureStatus);
  }

  public void disableAllFeatures() {
    assert client.isClientThread();
    for (StatelessFeature feature : getActiveFeatures()) {
      disableFeature(feature);
    }
  }

  /**
   * @return Thread safe view of the currently active features
   */
  public Set<StatelessFeature> getActiveFeatures() {
    return Set.copyOf(activeFeatures);
  }

  /**
   * Make sure a feature is in its correct state, that is disabled when disabled in the config and
   * vice versa
   *
   * @param feature The feature to check
   */
  @VisibleForTesting
  void updateFeatureStatus(@Nonnull StatelessFeature feature) {
    assert client.isClientThread();
    boolean isEnabledInConfig = feature.isEnabledInConfig();
    boolean wasEnabled = activeFeatures.contains(feature);

    if (!wasEnabled && isEnabledInConfig) {
      enableFeature(feature);
    } else if (wasEnabled && !isEnabledInConfig) {
      disableFeature(feature);
    }
  }

  /**
   * Enable a feature, meaning it is listing to events and generally acting as a mini-plugin
   *
   * @param feature The feature to enable
   */
  @VisibleForTesting
  void enableFeature(@Nonnull StatelessFeature feature) {
    assert client.isClientThread();
    log.debug("Enabling {}", feature.getConfigKey());
    eventBus.register(feature);
    activeFeatures.add(feature);
    feature.onEnable();
    if (feature instanceof StatefulFeature) {
      ((StatefulFeature) feature).reset();
    }
  }

  /**
   * Disable a feature, it will no longer receive events
   *
   * @param feature The feature to disable
   */
  @VisibleForTesting
  void disableFeature(@Nonnull StatelessFeature feature) {
    assert client.isClientThread();
    log.debug("Disabling {}", feature.getConfigKey());
    eventBus.unregister(feature);
    activeFeatures.remove(feature);
    feature.onDisable();
    if (feature instanceof StatefulFeature) {
      ((StatefulFeature) feature).reset();
    }
  }
}

